// Original transfer questions. Canonical indices of existing questions are untouched.
export const qualityQuestions=[];
export const qualityHelp={};
function Q(lesson,suffix,prompt,code,options,answer,steps,wrong,hint,thinking){
 const id='quality-'+suffix;
 qualityQuestions.push({id,lesson,prompt,code,options,answer,steps,explain:steps.join(' '),difficulty:'进阶',source:'本站原创 · 理解迁移'});
 qualityHelp[id]={hint,thinking,wrong};
}
Q('c-pointer-change','pointer-order','程序执行后 x、y 的值分别是多少？','#include <stdio.h>\nint main(void) {\n    int x=4, y=8;\n    int *p=&x;\n    int *q=p;\n    p=&y;\n    *q=6;\n    *p+=2;\n    printf("%d %d\\n", x, y);\n    return 0;\n}',['4 10','6 8','6 10','10 6'],2,['q=p 复制当时 p 保存的地址，因此 q 指向 x。','p=&y 只修改 p，q 没有自动跟着移动。','*q=6 写 x；*p+=2 写 y，由 8 变为 10。'],['忽略了 q 仍指向 x 并写入 6。','忽略了 p 指向 y 后对 y 的加二。','','把两个指针当前目标的归属颠倒了。'],'两个指针复制地址后，不会自动保持联动。','分别为 p、q 画独立格子，每次赋值只更新左侧对象，再沿各自箭头写值。');
Q('c-memcpy','overlap','以下目标是将前 4 个整数右移一位，哪种改法符合 C 的重叠复制要求？','#include <string.h>\nint a[5]={1,2,3,4,5};\n/* 将 a[0..3] 移到 a[1..4] */\nmemcpy(a+1, a, 4*sizeof a[0]);',['换成 memmove(a+1,a,4*sizeof a[0])','只把 a 声明为 volatile','仍用 memcpy，因为都是 int','把复制长度改为 sizeof(a+1)'],0,['源和目标覆盖的有效范围重叠。','memcpy 的非重叠前提不满足，不能依赖某次实现的复制方向。','memmove 提供重叠语义，字节数仍需保持为四个整数且目标范围有效。'],['','volatile 不给 memcpy 增加重叠保证。','元素类型相同不改变内存区间重叠事实。','sizeof(a+1) 求指针大小，不是四个整数的字节数。'],'先把源与目标画成两段地址区间。','标出两个半开区间是否相交，再核对函数保证和复制单位。');
Q('cpp-ctor','ctor-order','假设普通构造正常完成，下列输出顺序是什么？','#include <iostream>\nstruct Mark {\n    explicit Mark(int n) { std::cout << n; }\n};\nstruct Box {\n    Mark a;\n    Mark b;\n    Box(): b(2), a(1) {}\n};\nint main() { Box box; }',['21','只输出 1','编译必然失败','12'],3,['成员 a 在类内先声明，先初始化并输出 1。','成员 b 随后初始化并输出 2。','列表书写次序不改变成员声明顺序，本例没有读取未初始化成员。'],['按照初始化列表书写顺序推演了。','忽略了第二个成员也会被构造。','列表顺序不一致可产生警告，但本例不因此必然编译失败。',''],'先看类内声明顺序，不要先看列表的视觉顺序。','列出每个成员真正的初始化次序，再对应它的可观察动作。');
Q('cpp-copy','move-meaning','std::move(x) 后，为什么 y 仍会调用拷贝构造？','#include <iostream>\n#include <utility>\nstruct S {\n    S() = default;\n    S(const S&) { std::cout << "copy"; }\n};\nint main() { S x; S y(std::move(x)); }',['因为 std::move 永远就是拷贝','类没有可用移动构造，const 引用拷贝构造可接收该表达式','因为 y 必须先析构 x','因为编译器必须禁止所有移动'],1,['std::move 改变表达式类别，不直接指定最终构造函数。','本例用户声明了拷贝构造，没有可用的隐式移动构造。','const S& 能绑定这个表达式，因而选中拷贝构造并输出 copy。'],['std::move 可以使可用移动操作参与选择，并非永远拷贝。','','构造 y 不要求先销毁 x。','没有所有移动都被禁止的通用规则，只是本例没有可用移动构造。'],'区分表达式类别转换与真正被选择的构造函数。','列出这个类可用的构造重载，再判断参数能绑定到哪一种。');
Q('mem-sections','data-budget','常见 MCU 布局中 .data 初值为 2 KB、运行 .data 为 2 KB、.bss 为 6 KB，不含其他段。仅这些静态数据通常各贡献多少 Flash/RAM？','/* .data 的加载位置在 Flash，运行位置在 SRAM */',['Flash 0 KB，RAM 8 KB','Flash 8 KB，RAM 2 KB','Flash 2 KB，RAM 8 KB','Flash 2 KB，RAM 10 KB'],2,['Flash 保存 2 KB .data 初值。','.data 运行副本占 2 KB RAM，.bss 零初始化对象占 6 KB RAM。','因此计这几个部分为 Flash 2 KB、RAM 8 KB，不包括栈、堆和其他映像段。'],['漏掉 .data 的 Flash 初值。','把零初始化运行空间混算进了 Flash，并漏掉 RAM .bss。','','把同一 .data 加载字节再次计入 RAM。'],'先区分加载位置与运行位置。','给每一段列两栏，哪些有加载字节、哪些要运行存储，再按题设范围求和。');
Q('mem-cache','dma-cache','在带非一致性 D-Cache 的平台，CPU 修改发送缓冲后 DMA 仍发旧内容，最应先核对什么？','CPU: 更新 buffer\nDMA: 从主存读取 buffer\n观察: 线路上仍是旧字节',['对 buffer 使用 strlen','只把 DMA ISR 优先级提高','将 buffer 改名','发送前脏缓存清理、对齐范围与必要的顺序保证'],3,['CPU 的新写入可能仍在脏缓存，DMA 从主存看到旧内容。','发送前需按平台要求将相关缓存写回，并保证 DMA 在完成后读取。','缓存行对齐和范围需避免影响其他对象；此处前提是有对应数据缓存和非一致性路径。'],['字符串长度不能解决 CPU 与 DMA 的副本差异。','ISR 处理完成事件，不会自动清理发送前的脏缓存。','改名字不改变存储一致性。',''],'画出 CPU 与 DMA 各自访问的副本。','先确定数据方向，再选写回或失效操作，并核对维护粒度和时序。');
Q('arm-assembly','load-store','假设 r0 指向可写整数 5，执行片段后原内存是多少？','LDR r1, [r0]\nADD r1, r1, #1\n/* 没有 STR */',['5','6','r0 的地址数值','无法区分读写所以随机'],0,['LDR 把目标的 5 读入 r1。','ADD 只将 r1 改成 6。','未执行写回内存的 STR，所以原整数仍是 5。'],['','把寄存器副本修改当成内存写回。','r0 用作地址，没有被作为整数写进目标。','题设地址有效且操作明确，可以按读写对象推导。'],'寄存器和被读取的内存是不同状态。','每条指令列读取源与写入目标，检查是否出现真实存储指令。');
Q('arm-exception','fault-evidence','HardFault 的有效现场 PC 指向库 memcpy，下列排查顺序哪个更合理？','已保存可用异常帧与故障状态\n最近业务: 按收到的长度字段复制数据',['立刻把所有库函数替换成自写函数','先核对调用参数、长度范围与数据来源，再追踪首次非法访问','忽略现场，因为是库代码','只提高任务优先级'],1,['库函数可能只是第一个触发非法访问的位置。','未验证的长度或无效源目标可以让正确实现访问错误范围。','先检查现场与参数，再沿数据来源查首次错误；必要时用原条件复现。'],['没有证据表明所有库函数有问题，替换可能掩盖根因。','','有效现场能缩小问题，不能仅因位于库内就忽略。','任务优先级不修复无效地址或长度。'],'最后故障位置与最初破坏位置可能不同。','从故障指令的访问对象向前检查参数与边界，形成可验证假设。');
Q('ds-binary','empty-boundary','使用半开区间查首个 >=target 位置，空数组 n=0 时应有什么行为？','size_t lo=0, hi=n;\nwhile (lo<hi) { /* 按半开区间二分 */ }\nreturn lo;',['仍访问 a[0] 再返回','返回最后元素下标 n-1','不访问数组，返回 0 这一尾后位置','陷入循环'],2,['n=0 时 lo 与 hi 都是 0，lo<hi 为假。','循环不进入，不需要读取数组。','返回 0 等于 n，是合法边界结果；调用者应先检查 result<n 再访问。'],['循环条件阻止了对不存在元素的访问。','空数组没有最后有效元素，无符号 n-1 还可能回绕。','','lo 与 hi 都为零，循环条件为假，直接结束而不是死循环。'],'先用空输入检查区间表达是否仍有意义。','代入初值再检查循环条件，最后解释返回位置是否可以解引用。');
Q('ds-valley','valley-definition','按严格内部点定义，数组 {5,2,2,4,1,3} 有几个波谷？','/* 仅计 0<i<n-1 且 a[i]<a[i-1] && a[i]<a[i+1] */',['0','1','2','3'],1,['下标 1 和 2 的 2 与另一侧相等，不满足严格小于两侧。','下标 4 的 1 小于 4 和 3，是一个严格内部波谷。','首尾不按本题定义计入，所以总数为 1。'],['漏掉下标 4 的值 1，它严格小于两侧的 4 和 3。','','把平底区间当作本题的严格点计入。','同时混入重复平台或首尾，不符合定义。'],'严格小于与允许相等是两个判定。','先逐个内部位置写两项比较，再检查重复平台和边界是否计入。');
Q('os-sync','lost-update','两个任务交错执行 counter++，初值为 0，为什么可能最终只为 1？','A: 读取 counter -> 0\nB: 读取 counter -> 0\nA: 写入 0+1\nB: 写入 0+1',['因为 ++ 在 C 中定义为减法','因为任务 B 自动撤销 A','因为 volatile 保证覆盖','两次读改写未作为不可分割更新，发生丢失更新'],3,['两任务各自读取的旧值都是 0。','各自在局部计算新值 1 并写回。','第二次写入没有在第一次结果上增加，需匹配并发模型的同步或原子更新。'],['++ 是递增，问题在交错而非运算含义。','没有自动撤销步骤，是两个旧值计算结果互相覆盖。','volatile 不提供这样的原子读改写保证。',''],'看操作拆分和交错，不只看源码一行。','按读、算、写排列两个执行流，再找需要保护的整体。');
Q('os-deadlock','mutex-cycle','A 持锁 X 等 Y，B 持锁 Y 等 X。哪种设计最直接预防这种循环等待？','A: take(X); take(Y);\nB: take(Y); take(X);',['两任务都按 X 再 Y 的统一顺序获取','提高 A 的优先级','把锁变量声明 volatile','把等待时间都改得更长'],0,['两任务当前的资源等待形成 X-Y 闭环。','统一锁顺序让所有路径按同一方向获取，破坏这里的循环等待。','仍需正确释放、处理失败及限制持锁时长；优先级继承不能独自解开此闭环。'],['','提高等待者优先级不提供它缺少的锁。','volatile 不改变资源获取顺序。','延长等待只保留闭环，不预防形成。'],'CPU 调度与资源依赖是两层问题。','画持有边和等待边，找闭环，再判断哪种改法真正改变边关系。');
Q('stm32-uartdma','idle-half','协议帧含长度与 CRC。收到前半段后出现 UART IDLE，处理方式应是什么？','接收片段: 帧头 + 长度 + 部分载荷\n缺失: 其余载荷与 CRC',['直接执行已收到部分字段','立即把 CRC 当零','保留解析状态等待剩余字节，并有超时与容量限制','每次 IDLE 都无条件清空缓冲'],2,['IDLE 是线路空闲事件，不认识协议的完整长度。','已有片段缺少载荷和校验，不能执行完整命令。','保留有界状态，收到后续再验证；超时或非法长度走明确丢弃和重同步路径。'],['仍缺少剩余载荷与 CRC，不能证明完整合法，也不应直接执行。','缺失校验不可以伪造为零。','','无条件清空会丢掉合法分段帧。'],'分别识别接收事件与业务完成条件。','列已收与缺失字段，再按解析状态处理等待、超时和拒绝。');
Q('stm32-watchdog','health-feed','两个关键任务中一个卡死，但定时器仍无条件喂狗。改进方向是什么？','通信任务: 不再取得进展\n传感任务: 正常\n喂狗回调: 仍按时刷新',['让喂狗更频繁','由关键任务进展形成健康条件，满足后才刷新','取消所有错误日志','只扩大通信任务优先级'],1,['看门狗只观察刷新，不自动了解业务任务。','无条件喂狗把卡死隐藏在正常刷新后。','健康监控需要判断关键任务在本监控窗口是否有合理进展，并设计故障记录与恢复。'],['更频繁刷新仍掩盖失去进展。','','删除证据不会建立健康条件。','优先级变化不保证任务从逻辑卡死恢复。'],'刷新是否代表系统健康，是设计条件而不是硬件自动推断。','先定义各关键任务的有效进展证据，再决定哪些证据允许刷新。');
Q('p-spi','spi-first-edge','SPI 模式 3 的第一边沿与采样边沿分别是什么？','模式 3: CPOL=1, CPHA=1',['第一上升，采样上升','第一下降，采样下降','第一上升，采样下降','第一下降，采样上升'],3,['CPOL=1 使 SCK 空闲高，所以第一边沿是下降。','CPHA=1 在第二边沿采样。','第二边沿返回高电平，是上升；所以第一下降、采样上升。'],['空闲高的第一变化应向低。','CPHA=1 不是第一边沿采样。','第一边沿方向和采样位置都未按条件推导。',''],'先确定时钟空闲电平，第一边沿不总是上升沿。','先画空闲电平与两个边沿，再将 CPHA 的采样位置放进去。');
Q('p-throughput','baud-budget','UART 8N1、115200 baud，发送 2304 个载荷字节的理想线路耗时是多少？','/* 忽略软件间隙和业务额外头部 */',['约 200 ms','约 20 ms','约 2 ms','约 16 ms'],0,['8N1 每字节占 10 位线路时间。','共 2304×10=23040 位。','23040/115200=0.2 秒，即 200 ms；真实耗时可能更大。'],['','按每字节一位估算，漏掉帧位。','数量级再少十倍，未按帧位与速率换算。','没有按 10 位一字节的规定换算。'],'把 baud、位与有效字节放在同一单位系统中。','先数总线路位，再除位速率，最后换成毫秒。');
Q('r-queue','queue-own','队列元素为指针，发送成功后消费者尚未读取，发送者应如何处理独占消息缓冲？','发送成功转移消息所有权\n消费者处理后归还缓冲池',['立即 free，再把发送者指针置 NULL','立即重用，因为队列复制了整个目标','按约定保持目标有效，不再改写，等接收方归还','把目标声明 volatile 后立即重用'],2,['本题队列保存地址而非目标字节。','发送成功后所有权交给接收方，接收前后需要保持目标有效。','发送者不能重写或释放，归还事件才允许重新获取使用。'],['置空发送者变量不会修复队列中的悬空地址。','队列只复制指针元素，不自动深拷贝目标。','','volatile 不防止消费者看到重写内容。'],'先区分队列元素和元素指向的数据。','按发送成功、接收、处理和归还画所有权变化，另列发送失败路径。');
Q('r-priority-inversion','inherit-not-deadlock','优先级继承临时提高持锁任务，主要减少哪部分等待？','L 持锁，H 阻塞等待同一锁，M 在 L 与 H 的优先级之间',['消除 L 的全部业务处理时间','减少 M 对 L 的额外抢占拖延','自动释放 H 所需锁','自动解开全部多锁死锁'],1,['H 必须等 L 完成并释放。','M 的抢占可以额外拖延 L，继承给 L 更高有效优先级，减少这类影响。','L 的必要工作和可能的其他锁依赖仍存在，继承不是自动完成业务或解开死锁。'],['L 的受保护工作仍需执行。','','继承不自动释放锁，持有者仍需执行正确路径并归还资源。','资源依赖闭环与中间抢占不同。'],'把必要持锁工作与中间任务造成的额外等待分开。','比较继承前后 L 的运行机会，不改变资源依赖与必需处理量。');
Q('linux-fork','fork-paths','单线程程序中 fork 成功后，下列哪种结论成立？','pid_t pid=fork();\nif (pid==0) { /* 子分支 */ }\nelse if (pid>0) { /* 父分支 */ }',['父分支一定先打印','子分支一定先打印','普通变量自动成为共享变量','父子从调用返回继续，先后通常不能仅凭这段保证'],3,['成功创建子进程，父得到子 PID，子得到 0。','两者分别继续，后续顺序受调度与同步影响。','普通用户变量不是由 fork 自动转为共享数据，需要另行通信或共享机制。'],['题目没有同步条件保证父进程先运行，返回值不建立执行先后。','题目没有同步条件保证子进程先运行，新创建也不保证先取得 CPU。','地址空间语义不等同显式共享内存。',''],'返回值决定路径，调度决定运行机会。','先画父子分支，再检查是否存在能证明顺序的同步条件。');
Q('linux-devicetree','dtb-stale','改 DTS 后设备仍没进 probe，最先补哪类证据？','编译目录中的 DTS 已改\n尚未确认启动时实际使用哪份 DTB',['实际加载的 DTB、运行节点 status 与 compatible','只改驱动函数名','反复 chmod 777 一个不存在的设备节点','只增加应用线程'],0,['修改源文件不证明新的 DTB 已编译并被启动链加载。','先核对运行中真实设备树、节点状态和匹配字符串。','确认描述有效后再查驱动配置、资源和 probe 错误，避免在错误层猜测。'],['','函数名改动不验证设备描述链。','节点不存在时权限操作不能建立匹配。','应用线程不替代内核设备匹配。'],'区分编辑中的源描述与运行中生效描述。','按编译、加载、状态、匹配和初始化逐层找证据。');
Q('e-debug','timing-log','增加日志后偶发竞态消失，最合理的下一步是什么？','旧版本: 偶发数据错乱\n加入多条 printf 后: 暂未复现',['宣告修复并删除复现条件','验证日志是否改变时序，低干扰采集共享状态并复测原条件','删除所有同步代码','只统计源码行数'],1,['日志可改变调度、栈和 I/O 时延，可能隐藏交错。','没有针对共享协议的修复证据，不能因未复现就下结论。','应选择低干扰记录，验证原假设并回归原压力路径。'],['把暂未复现当成根因已修复。','','删除同步更可能破坏状态。','源码行数不能描述共享操作交错，需要记录与验证执行时序。'],'观察手段也会影响正在观察的系统。','列日志新增的时延与资源，再设计能区分假设的低干扰实验。');
Q('e-fsm','fault-state','故障状态收到启动命令，状态机设计应优先明确什么？','当前: FAULT\n事件: START\n故障清除条件尚不满足',['只要收到了就直接启动','只修改一个 running 标志','允许条件、拒绝行为与恢复转移，维持安全状态','删除 FAULT 状态'],2,['事件到达不意味着当前状态允许动作。','需要定义故障解除前对 START 的处理及恢复条件。','先保持安全不变量，再按可验证条件转移，防止布尔标志冲突。'],['当前仍处故障状态，直接启动绕过保护条件，可能触发不允许的动作。','可能制造 running 与 FAULT 同时为真的矛盾。','','删除状态不能移除实际故障。'],'状态决定允许事件，不只看命令内容。','检查当前状态、保护条件和失败出口，再安排动作。');
Q('n-tcpudp','tcp-frames','TCP 接收得到半条消息，下一次得到剩余部分和第二条消息，解析器应怎样处理？','第一块: 消息 A 的前缀\n第二块: A 的后缀 + 消息 B',['每次 recv 当一条完整消息','丢弃第一块再解析第二块','把两块都作为 A 无限制合并','保存前缀，按应用长度完成 A，再继续解析剩余 B'],3,['TCP 是字节流，不保持发送或接收调用边界。','解析器保存未完成数据，长度满足并验证后消费 A。','剩余字节可能构成 B 或 B 的前缀，应继续处理而不是丢弃。'],['把 API 调用边界当协议边界。','丢掉合法前缀会破坏 A。','必须按业务长度消费，不能把后续帧无限并入。',''],'传输块与业务消息是两种边界。','标每条业务消息的长度，按已消费字节移动读位置并保留尾部。');
Q('n-mqtt','business-once','跨多个服务重试一个设备控制命令，为什么业务还常需请求 ID 与幂等处理？','协议交付完成\n上层服务因超时重发同一业务请求',['业务重试可能独立于单次协议交付，需识别重复副作用','QoS 会把全部数据库和电机动作合成一笔事务','保留消息会自动删除全部历史重复','只要主题名相同就不会重复执行'],0,['单次协议交付与跨服务业务事务不是同一范围。','上层重试可能再次产生请求，应明确同一事务身份和处理结果。','幂等或去重策略依据业务要求设计，不只依赖协议等级。'],['','交付机制不自动覆盖全部外部副作用。','保留消息表示最近状态，不是通用业务去重日志。','主题相同不定义唯一请求。'],'分开协议消息、业务请求与执行副作用。','画上层重试与设备执行路径，确定在哪里识别同一请求。');
Q('pr-watch','project-evidence','面试讲低功耗优化，哪种结果表达最便于核查？','已做过一次 Stop 唤醒与电流测试',['只说用了 STM32 和 FreeRTOS','说明型号、供电和测量条件、进入恢复路径、前后观测及个人负责范围','宣称任何模式都零功耗','把团队全部功能描述为自己独立完成'],1,['工程结果需要条件和实现对应，模式名本身不足以证明收益。','真实测量、恢复验证和职责范围让结果可核查。','未测指标不应编造，可明确已验证与尚待验证部分。'],['技术名词没有展示约束、行为和证据。','','零功耗与真实运行条件不符，且没有测量依据。','职责失真使追问无法核对。'],'项目讲述先找可验证的证据与负责边界。','按需求、方案、测量条件和结果列事实，避免没有条件的绝对结论。');
Q('pr-robot','motor-chain','日志证实收到合法控制命令，但电机不动，哪组下一步证据更有效？','已确认: 上位机发送、UART 接收、协议校验\n未知: 实际执行链',['把命令变量改成长名字','只提高串口波特率','供电、驱动使能、安全状态、实际 PWM 或总线输出与反馈','立即重写全部项目'],2,['已确认的通信层不能证明驱动与输出层。','继续沿能量和控制链检查，定位首次不符合预期的接口。','记录实际信号与安全条件，再形成最小修复和回归。'],['变量名字长度不改变供电、使能或实际控制信号，无法提供定位证据。','收包已合法，速率不直接解释缺失输出。','','没有定位就重写会丢失证据且扩大发生变化的范围。'],'沿数据与能量路径找首个未验证环节。','给每个接口写预期与观测，把缺失证据变成具体测量。');
